case_nested_in_loop_with_label.sql:
CREATE PROCEDURE p()
L1: BEGIN
  DECLARE a INTEGER DEFAULT 0;
  WHILE a < 10 DO
    CASE
      WHEN a = 5 THEN
        LEAVE L1;
      ELSE
        SET a = a + 1;
    END CASE;
  END WHILE;
END L1;

