  DECLARE s VARCHAR(100);
  DECLARE c CURSOR WITH RETURN ONLY FOR st;
  SET s = 'SELECT a FROM t WHERE ? = b AND ? = d;';
  PREPARE st FROM s;
  OPEN c USING v1, v2;
END;

