while_iterate.sql:
lbl: WHILE v > 0 DO
  SET v = v - 1;
  ITERATE lbl;
END WHILE lbl;

while_label_leave.sql:
lbl: WHILE v > 0 DO
  IF v = 5 THEN
    LEAVE lbl;
  END IF;
  SET v = v - 1;
END WHILE lbl;

